const out = [];

for (const item of $input.all()) {

  const category = item.json.category || 'science';

  let entries = item.json.feed?.entry ?? [];

  if (!Array.isArray(entries)) {
    entries = [entries];
  }

  for (const e of entries) {

    const title = String(e.title ?? '')
      .replace(/\s+/g, ' ')
      .trim();

    const content = String(e.summary ?? '')
      .replace(/\s+/g, ' ')
      .trim();

    if (content.length < 200) continue;

    const rawId = String(e.id ?? '');

    const arxivId = rawId
      .split('/abs/')[1]
      ?.replace(/v\d+$/, '');

    if (!arxivId) continue;

    out.push({
      json: {
        external_id: `arxiv:${arxivId}`,

        title,

        content,

        source: 'arxiv',

        source_type: 'science_research',

        category,

        url: rawId,

        metadata: {
          arxiv_id: arxivId,
          published_at: String(e.published ?? '').slice(0, 10),
          updated_at: String(e.updated ?? '').slice(0, 10),
          language: 'en'
        }
      }
    });
  }
}

return out;

