const SIZE = 2000;
const OVERLAP = 300;

const out = [];

for (const item of $('dedup docs').all()) {
  const d = item.json;

  const text = d.content || '';

  if (!text.trim()) continue;

  let start = 0;
  let idx = 0;

  while (start < text.length) {

    const content = text.slice(start, start + SIZE);

    out.push({
      json: {
        external_id: d.external_id,
        chunk_index: idx++,
        content: content,

        metadata: {
          category: d.category,
          source: d.source,
          published_at: d.metadata?.published_at || null,
          title: d.title,
          external_id: d.external_id
        }
      }
    });

    if (start + SIZE >= text.length) {
      break;
    }

    start += SIZE - OVERLAP;
  }
}

return out;

const chunks = $('chunk').all();
return $input.all().map((item, i) => ({ json: {
  ...chunks[i].json,
  embedding: '[' + item.json.embedding.values.join(',') + ']',
  metadata_json: JSON.stringify(chunks[i].json.metadata),
}}));

parameters.query:
insert into chunks (document_id, chunk_index, content, embedding, metadata)
values (
  (select id from documents where metadata->>'external_id' = $1),
  $2, $3, $4::vector, $5::jsonb
)
on conflict (document_id, chunk_index) do nothing;

