const items = $input.all();

const result = [];

for (const item of items) {
  const channel = item.json.rss?.channel;
  const articles = channel?.item || [];

  for (const article of articles) {

    const guid = typeof article.guid === 'object'
      ? article.guid._
      : article.guid;

    result.push({
      json: {
        external_id: `bbc:${guid || article.link}`,

        title: article.title,

        content: article.description || article.title,

        source: 'bbc_reuters',

        source_type: 'news_events',

        category: 'news',

        url: article.link,

        metadata: {
          publisher: 'BBC',
          guid: guid || null,
          published_at: article.pubDate || null,
          image: article['media:thumbnail']?.['@_url'] || null
        }
      }
    });
  }
}

return result;

const newDocuments = $('Merge').all();
const existingDocuments = $('get existing docs').all();

const existingIds = new Set(
  existingDocuments
    .map(item => item.json.external_id)
    .filter(Boolean)
);

return newDocuments.filter(item => {
  const externalId = item.json.external_id;

  return externalId && !existingIds.has(externalId);
});
